5	namespace AtrioTeam\DigitalHub\Api;
6	
7	use Illuminate\Database\Eloquent\Model;
8	use Illuminate\Http\Resources\Json\JsonResource;
9	use InvalidArgumentException;
10	
11	/**
12	 * Registro delle entità esposte dall'API esterna di lettura (roadmap #24).
13	 *
14	 * Il core non conosce i modelli di dominio del template (Designer, Product, …):
15	 * il template li dichiara in `config('digital-hub.api.resources')` come
16	 * `slug => ['model' => ..., 'resource' => ..., 'with' => [...]]`, dove
17	 * `resource` è la JsonResource che decide la forma del payload — cioè il punto
18	 * in cui gli attributi PIM vengono risolti (design admin, Parte 3).
19	 *
20	 * Solo ciò che è dichiarato qui è raggiungibile: non c'è modo di indirizzare un
21	 * modello per nome di classe dalla request.
22	 */
23	class ApiResourceRegistry
24	{
25	    /**
26	     * @return list<string>
27	     */
28	    public function slugs(): array
29	    {
30	        return array_values(array_filter(array_keys($this->config()), is_string(...)));
31	    }
32	
33	    public function has(string $slug): bool
34	    {
35	        return isset($this->config()[$slug]);
36	    }
37	
38	    /**
39	     * @return class-string<Model>
40	     */
41	    public function modelClass(string $slug): string
42	    {
43	        $model = $this->definition($slug)['model'] ?? null;
44	
45	        if (! is_string($model) || ! is_subclass_of($model, Model::class)) {
46	            throw new InvalidArgumentException("Risorsa API [{$slug}]: chiave 'model' mancante o non è un Eloquent model.");
47	        }
48	
49	        return $model;
50	    }
51	
52	    /**
53	     * @return class-string<JsonResource>
54	     */
55	    public function jsonResourceClass(string $slug): string
56	    {
57	        $resource = $this->definition($slug)['resource'] ?? null;
58	
59	        if (! is_string($resource) || ! is_subclass_of($resource, JsonResource::class)) {
60	            throw new InvalidArgumentException("Risorsa API [{$slug}]: chiave 'resource' mancante o non è una JsonResource.");
61	        }
62	
63	        return $resource;
64	    }
65	
66	    /**
67	     * Relazioni da eager-loadare per evitare N+1 nella serializzazione.
68	     *
69	     * @return list<string>
70	     */
71	    public function eagerLoads(string $slug): array
72	    {
73	        $with = $this->definition($slug)['with'] ?? [];
74	
75	        return is_array($with) ? array_values(array_filter($with, is_string(...))) : [];
76	    }
77	
78	    public function newModel(string $slug): Model
79	    {
80	        $class = $this->modelClass($slug);
81	
82	        return new $class();
83	    }
84	
85	    /**
86	     * @return array<string, mixed>
87	     */
88	    private function definition(string $slug): array
89	    {
90	        $definition = $this->config()[$slug] ?? null;
91	
92	        if (! is_array($definition)) {
93	            throw new InvalidArgumentException("Risorsa API [{$slug}] non dichiarata in config('digital-hub.api.resources').");
94	        }
95	
96	        /** @var array<string, mixed> $definition */
97	        return $definition;
98	    }
99	
100	    /**
101	     * @return array<string, mixed>
102	     */
103	    private function config(): array
104	    {
105	        $resources = config('digital-hub.api.resources', []);
106	
107	        if (! is_array($resources)) {
108	            return [];
109	        }
110	
111	        /** @var array<string, mixed> $resources */
112	        return $resources;
113	    }
114	}
