5	namespace AtrioTeam\DigitalHub\Api\Http\Controllers;
6	
7	use AtrioTeam\DigitalHub\Api\ApiResourceRegistry;
8	use Illuminate\Contracts\Support\Responsable;
9	use Illuminate\Database\Eloquent\Builder;
10	use Illuminate\Database\Eloquent\Model;
11	use Illuminate\Http\Request;
12	use Symfony\Component\HttpKernel\Exception\NotFoundHttpException;
13	
14	/**
15	 * Controller unico dell'API esterna di lettura (roadmap #24): l'entità arriva
16	 * come slug di route ed è risolta dal {@see ApiResourceRegistry}, che il
17	 * template popola.
18	 *
19	 * La paginazione è cursor-less (page/per_page) perché il consumatore itera fino
20	 * all'ultima pagina, non naviga.
21	 */
22	class ApiResourceController
23	{
24	    public function __construct(private readonly ApiResourceRegistry $registry)
25	    {
26	    }
27	
28	    public function index(Request $request, string $resource): Responsable
29	    {
30	        $this->guardResource($resource);
31	
32	        /** @var array<string, mixed> $validated */
33	        $validated = $request->validate([
34	            'updated_since' => ['sometimes', 'date'],
35	            'per_page' => ['sometimes', 'integer', 'min:1', 'max:200'],
36	        ]);
37	
38	        $query = $this->query($resource);
39	
40	        if (isset($validated['updated_since'])) {
41	            $query->where('updated_at', '>=', $validated['updated_since']);
42	        }
43	
44	        $perPage = $validated['per_page'] ?? config('digital-hub.api.per_page', 50);
45	        $perPage = is_numeric($perPage) ? (int) $perPage : 50;
46	
47	        $jsonResource = $this->registry->jsonResourceClass($resource);
48	
49	        return $jsonResource::collection(
50	            $query->orderBy($query->getModel()->getKeyName())->paginate($perPage)->withQueryString(),
51	        );
52	    }
53	
54	    /**
55	     * `{identifier}` è l'id numerico oppure il `global_id` (`{table}:{id}`), che
56	     * è la chiave di join cross-sistema con il CMS (design admin, Parte 1).
57	     */
58	    public function show(string $resource, string $identifier): Responsable
59	    {
60	        $this->guardResource($resource);
61	
62	        $query = $this->query($resource);
63	        $model = $query->getModel();
64	
65	        $record = ctype_digit($identifier)
66	            ? $query->find($identifier)
67	            : $query->where($model->qualifyColumn('global_id'), $identifier)->first();
68	
69	        if (! $record instanceof Model) {
70	            throw new NotFoundHttpException('Record non trovato.');
71	        }
72	
73	        $jsonResource = $this->registry->jsonResourceClass($resource);
74	
75	        return new $jsonResource($record);
76	    }
77	
78	    /**
79	     * @return Builder<Model>
80	     */
81	    private function query(string $resource): Builder
82	    {
83	        return $this->registry->newModel($resource)->newQuery()
84	            ->with($this->registry->eagerLoads($resource));
85	    }
86	
87	    /**
88	     * Slug non dichiarato = 404, non 500: dal punto di vista del client è una
89	     * risorsa che non esiste.
90	     */
91	    private function guardResource(string $resource): void
92	    {
93	        if (! $this->registry->has($resource)) {
94	            throw new NotFoundHttpException("Risorsa [{$resource}] non esposta dall'API.");
95	        }
96	    }
97	}
